mapper.select:
SELECT p.id, p.user_id, u.username, u.avatar, p.title, p.content, p.images, p.status, p.reject_reason, p.view_count, p.like_count, p.create_time FROM t_community_post p LEFT JOIN t_user u ON p.user_id = u.id WHERE p.deleted_flag = 0
AND (p.title LIKE CONCAT('%', #{query.keyword}, '%') OR p.content LIKE CONCAT('%', #{query.keyword}, '%'))
AND p.status = #{query.status}
AND p.user_id = #{query.userId}
ORDER BY p.create_time DESC
